package com.johnny.hotel.payroll;import com.johnny.hotel.payroll.PayrollModels.*;import org.apache.ibatis.annotations.*;import java.time.LocalDate;import java.time.LocalDateTime;import java.util.*;
@Mapper public interface PayrollMapper{
 @Select("SELECT id FROM sys_user WHERE id=#{id} FOR UPDATE")Long lockEmployee(Long id);@Select("SELECT id FROM hotel_business_date_control WHERE id=1 FOR UPDATE")Integer lockPayrollScope();
 @Select("SELECT * FROM employee_compensation_profile WHERE id=#{id}")Compensation compensation(Long id);@Select("SELECT * FROM employee_compensation_profile WHERE employee_id=#{employee} ORDER BY effective_from DESC,id DESC LIMIT #{offset},#{size}")List<Compensation> compensationHistory(@Param("employee")Long employee,@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM employee_compensation_profile WHERE employee_id=#{employee}")long compensationCount(Long employee);@Update("UPDATE employee_compensation_profile SET status=0 WHERE id=#{id} AND status=1")int deactivateCompensation(Long id);
 @Select("SELECT COUNT(*) FROM employee_compensation_profile WHERE employee_id=#{employee} AND status=1 AND effective_from<=#{to} AND (effective_to IS NULL OR effective_to>=#{from}) FOR UPDATE")int compensationOverlap(@Param("employee")Long employee,@Param("from")LocalDate from,@Param("to")LocalDate to);@Select("SELECT * FROM employee_compensation_profile WHERE employee_id=#{employee} AND status=1 AND effective_from<=#{start} AND (effective_to IS NULL OR effective_to>=#{end}) ORDER BY effective_from DESC,id DESC LIMIT 1 FOR UPDATE")Compensation coveringCompensation(@Param("employee")Long employee,@Param("start")LocalDate start,@Param("end")LocalDate end);
 @Insert("INSERT INTO employee_compensation_profile(employee_id,pay_type,currency,base_amount,hourly_rate,effective_from,effective_to,status,reason,created_by,approved_by,approved_at) VALUES(#{employeeId},#{payType},#{currency},#{baseAmount},#{hourlyRate},#{effectiveFrom},#{effectiveTo},1,#{reason},#{createdBy},#{approvedBy},#{approvedAt})")@Options(useGeneratedKeys=true,keyProperty="id")int insertCompensation(Compensation c);
 @Select("SELECT COALESCE(MAX(version_no),0) FROM payroll_policy FOR UPDATE")int maxPolicyVersion();@Select("SELECT * FROM payroll_policy WHERE status='ACTIVE' FOR UPDATE")Policy activePolicy();@Select("SELECT * FROM payroll_policy WHERE status='ACTIVE'")Policy currentPolicy();@Select("SELECT * FROM payroll_policy WHERE id=#{id}")Policy policy(Long id);@Update("UPDATE payroll_policy SET status='INACTIVE' WHERE status='ACTIVE'")int deactivatePolicy();@Insert("INSERT INTO payroll_policy(version_no,status,monthly_unpaid_mode,hourly_paid_leave_mode,standard_days,standard_hours_per_day,rounding_mode,created_by,activated_by,activated_at) VALUES(#{versionNo},'ACTIVE',#{monthlyUnpaidMode},#{hourlyPaidLeaveMode},#{standardDays},#{standardHoursPerDay},#{roundingMode},#{createdBy},#{activatedBy},#{activatedAt})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPolicy(Policy p);
 @Select("SELECT * FROM payroll_period WHERE id=#{id}")Period period(Long id);@Select("SELECT * FROM payroll_period WHERE id=#{id} FOR UPDATE")Period lockPeriod(Long id);@Select("SELECT * FROM payroll_period WHERE created_by=#{actor} AND request_key=#{key}")Period periodByKey(@Param("actor")Long actor,@Param("key")String key);@Select("SELECT COUNT(*) FROM payroll_period WHERE status<4 AND period_start<#{end} AND period_end>#{start} FOR UPDATE")int periodOverlap(@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);@Insert("INSERT INTO payroll_period(period_start,period_end,currency,status,policy_id,created_by,request_key) VALUES(#{periodStart},#{periodEnd},#{currency},0,#{policyId},#{createdBy},#{requestKey})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPeriod(Period p);@Select("SELECT * FROM payroll_period ORDER BY period_start DESC,id DESC LIMIT #{offset},#{size}")List<Period> periods(@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM payroll_period")long periodCount();
 @Insert("INSERT INTO payroll_period_employee(payroll_period_id,employee_id) VALUES(#{period},#{employee})")int addEmployee(@Param("period")Long period,@Param("employee")Long employee);@Select("SELECT employee_id FROM payroll_period_employee WHERE payroll_period_id=#{period} ORDER BY employee_id")List<Long> eligibleEmployees(Long period);
 @Select("SELECT * FROM payroll_payslip WHERE payroll_period_id=#{period} AND employee_id=#{employee} FOR UPDATE")Payslip lockPayslipByEmployee(@Param("period")Long period,@Param("employee")Long employee);@Select("SELECT * FROM payroll_payslip WHERE id=#{id} FOR UPDATE")Payslip lockPayslip(Long id);@Select("SELECT * FROM payroll_payslip WHERE id=#{id}")Payslip payslip(Long id);
 @Insert("INSERT INTO payroll_payslip(payroll_period_id,employee_id,compensation_profile_id,status,blocked_reason,pay_type,currency,rate_snapshot,worked_minutes,attendance_session_count,attendance_anomaly_count,correction_fact_count,paid_leave_amount,unpaid_leave_amount,leave_snapshot,policy_snapshot,base_pay,attendance_based_pay,paid_leave_pay,unpaid_leave_deduction,allowances,bonuses,manual_deductions,other_adjustments,gross_pay,total_deductions,net_pay,calculated_at) VALUES(#{payrollPeriodId},#{employeeId},#{compensationProfileId},#{status},#{blockedReason},#{payType},#{currency},#{rateSnapshot},#{workedMinutes},#{attendanceSessionCount},#{attendanceAnomalyCount},#{correctionFactCount},#{paidLeaveAmount},#{unpaidLeaveAmount},#{leaveSnapshot},#{policySnapshot},#{basePay},#{attendanceBasedPay},#{paidLeavePay},#{unpaidLeaveDeduction},#{allowances},#{bonuses},#{manualDeductions},#{otherAdjustments},#{grossPay},#{totalDeductions},#{netPay},#{calculatedAt})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPayslip(Payslip p);
 @Update("UPDATE payroll_payslip SET compensation_profile_id=#{compensationProfileId},status=#{status},blocked_reason=#{blockedReason},pay_type=#{payType},rate_snapshot=#{rateSnapshot},worked_minutes=#{workedMinutes},attendance_session_count=#{attendanceSessionCount},attendance_anomaly_count=#{attendanceAnomalyCount},correction_fact_count=#{correctionFactCount},paid_leave_amount=#{paidLeaveAmount},unpaid_leave_amount=#{unpaidLeaveAmount},leave_snapshot=#{leaveSnapshot},policy_snapshot=#{policySnapshot},base_pay=#{basePay},attendance_based_pay=#{attendanceBasedPay},paid_leave_pay=#{paidLeavePay},unpaid_leave_deduction=#{unpaidLeaveDeduction},allowances=#{allowances},bonuses=#{bonuses},manual_deductions=#{manualDeductions},other_adjustments=#{otherAdjustments},gross_pay=#{grossPay},total_deductions=#{totalDeductions},net_pay=#{netPay},calculated_at=#{calculatedAt} WHERE id=#{id} AND status IN(0,1)")int updatePayslip(Payslip p);
 @Select("SELECT COALESCE(SUM(TIMESTAMPDIFF(MINUTE,GREATEST(effective_check_in,#{start}),LEAST(COALESCE(effective_check_out,#{end}),#{end}))),0) worked_minutes,COUNT(*) session_count,COALESCE(SUM(CASE WHEN effective_check_out IS NULL THEN 1 ELSE 0 END),0) anomaly_count,(SELECT COUNT(*) FROM attendance_correction_fact f JOIN attendance_session x ON x.id=f.session_id WHERE x.employee_id=#{employee} AND x.effective_check_in<#{end} AND COALESCE(x.effective_check_out,#{end})>#{start}) correction_count FROM attendance_session WHERE employee_id=#{employee} AND effective_check_in<#{end} AND COALESCE(effective_check_out,#{end})>#{start}")AttendanceInput attendance(@Param("employee")Long employee,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);@Select("SELECT t.unit,t.paid_treatment,SUM(r.requested_amount) amount FROM employee_leave_request r JOIN leave_type t ON t.id=r.leave_type_id WHERE r.employee_id=#{employee} AND r.status=2 AND r.start_at<#{end} AND r.end_at>#{start} GROUP BY t.unit,t.paid_treatment")List<LeaveInput> leaves(@Param("employee")Long employee,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);@Select("SELECT COUNT(*) FROM employee_leave_request WHERE employee_id=#{employee} AND status=2 AND start_at<#{end} AND end_at>#{start} AND (start_at<#{start} OR end_at>#{end})")int crossingLeaves(@Param("employee")Long employee,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);
 @Select("SELECT * FROM payroll_adjustment WHERE payslip_id=#{payslip} ORDER BY id")List<Adjustment> adjustments(Long payslip);@Select("SELECT * FROM payroll_adjustment WHERE payslip_id=#{payslip} AND request_key=#{key}")Adjustment adjustmentByKey(@Param("payslip")Long payslip,@Param("key")String key);@Insert("INSERT INTO payroll_adjustment(payslip_id,adjustment_type,direction,amount,reason,created_by,request_key) VALUES(#{payslipId},#{adjustmentType},#{direction},#{amount},#{reason},#{createdBy},#{requestKey})")@Options(useGeneratedKeys=true,keyProperty="id")int insertAdjustment(Adjustment a);
 @Update("UPDATE payroll_period SET status=1 WHERE id=#{id} AND status=0")int calculated(Long id);@Select("SELECT COUNT(*) FROM payroll_payslip WHERE payroll_period_id=#{period} AND status=1")int blocked(Long period);@Update("UPDATE payroll_period SET status=2,approved_by=#{actor},approved_at=#{at} WHERE id=#{id} AND status=1")int approvePeriod(@Param("id")Long id,@Param("actor")Long actor,@Param("at")LocalDateTime at);@Update("UPDATE payroll_payslip SET status=2,approved_at=#{at} WHERE payroll_period_id=#{period} AND status=0")int approvePayslips(@Param("period")Long period,@Param("at")LocalDateTime at);
 @Select("SELECT * FROM payroll_payslip WHERE payroll_period_id=#{period} ORDER BY employee_id LIMIT #{offset},#{size}")List<Payslip> payslips(@Param("period")Long period,@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM payroll_payslip WHERE payroll_period_id=#{period}")long payslipCount(Long period);@Select("SELECT * FROM payroll_payslip WHERE employee_id=#{employee} AND status IN(2,3) ORDER BY id DESC LIMIT #{offset},#{size}")List<Payslip> mine(@Param("employee")Long employee,@Param("offset")int offset,@Param("size")int size);@Select("SELECT COUNT(*) FROM payroll_payslip WHERE employee_id=#{employee} AND status IN(2,3)")long mineCount(Long employee);
 @Select("SELECT * FROM payroll_payment WHERE payslip_id=#{payslip}")Payment payment(Long payslip);@Insert("INSERT INTO payroll_payment(payslip_id,amount,payment_method,external_reference,request_key,paid_by,posting_business_date,paid_at,expense_id) VALUES(#{payslipId},#{amount},#{paymentMethod},#{externalReference},#{requestKey},#{paidBy},#{postingBusinessDate},#{paidAt},#{expenseId})")@Options(useGeneratedKeys=true,keyProperty="id")int insertPayment(Payment p);@Update("UPDATE payroll_payslip SET status=3,paid_at=#{at},expense_id=#{expense} WHERE id=#{id} AND status=2")int paidPayslip(@Param("id")Long id,@Param("at")LocalDateTime at,@Param("expense")Long expense);@Update("UPDATE payroll_period SET status=3,paid_at=#{at} WHERE id=#{id} AND status=2 AND NOT EXISTS(SELECT 1 FROM payroll_payslip WHERE payroll_period_id=#{id} AND status<>3)")int paidPeriod(@Param("id")Long id,@Param("at")LocalDateTime at);@Update("UPDATE payroll_period SET status=4,closed_at=#{at} WHERE id=#{id} AND status=3")int closePeriod(@Param("id")Long id,@Param("at")LocalDateTime at);
 @Select("SELECT (SELECT COUNT(*) FROM attendance_correction_fact f JOIN attendance_session s ON s.id=f.session_id JOIN payroll_period p ON p.id=#{period} WHERE s.employee_id=#{employee} AND f.create_time>#{calculated} AND s.effective_check_in<p.period_end AND COALESCE(s.effective_check_out,p.period_end)>p.period_start)+(SELECT COUNT(*) FROM employee_leave_request l JOIN payroll_period p ON p.id=#{period} WHERE l.employee_id=#{employee} AND l.decided_at>#{calculated} AND l.start_at<p.period_end AND l.end_at>p.period_start)")int sourceChanges(@Param("period")Long period,@Param("employee")Long employee,@Param("calculated")LocalDateTime calculated);@Insert("INSERT INTO payroll_action_history(period_id,payslip_id,action_type,actor_user_id,detail) VALUES(#{period},#{payslip},#{action},#{actor},#{detail})")int action(@Param("period")Long period,@Param("payslip")Long payslip,@Param("action")String action,@Param("actor")Long actor,@Param("detail")String detail);
}
